	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		tool.addPlugin(typeof(DataTypeManagerPlugin).getName());

		ToyProgramBuilder builder = new ToyProgramBuilder("Test", true);
		program = builder.getProgram();
